419)))),
filt AS (SELECT * FROM b WHERE 1=1 AND ('${marca:text}'='All' OR marca_f IN (${marca:sqlstring})) AND ('${banco:text}'='All' OR CAST(TRY_CAST(cbe_f AS INTEGER) AS VARCHAR) IN (${banco:sqlstring})) AND ('${motivo_emisor:text}'='All' OR ciss_norm IN (${motivo_emisor:sqlstring})) AND ('${motivo_adqte:text}'='All' OR nri IN (${motivo_adqte:sqlstring})))
